.blog-main{ padding-top:clamp(.6rem,2vw,1rem); }
html.blog-lock, html.blog-lock body{ overflow:hidden; }
.blog-modal{ overscroll-behavior:contain; }
/* Extra breathing room: Why switch / 4 steps / stats */
.benefits .section-title, .how .section-title{ margin-bottom: clamp(2.2rem, 5vw, 3.2rem); }
.benefits{ padding-top: clamp(2.4rem, 6vw, 4rem); padding-bottom: clamp(1.6rem, 4vw, 2.6rem); }
.how{ padding-top: clamp(3rem, 7vw, 5rem); padding-bottom: clamp(3rem, 7vw, 5rem); }
.benefit-grid{ gap: clamp(1.6rem, 4vw, 3rem); }
.benefit{ padding-top: 1.4rem; }
.benefit h3{ margin-bottom: .8rem; }
.how-steps{ gap: clamp(1.6rem, 3.5vw, 2.6rem); }
.how-steps li{ padding-top: 1.4rem; }
.how-steps i{ margin-bottom: 1rem; }
.how-steps h3{ margin: 0 0 .7rem; }
.trust-strip{ margin-top: clamp(3.4rem, 7vw, 5rem); padding: 1.6rem 1.2rem; }
.trust-strip li{ line-height: 1.5; }
.trust-strip b{ margin-bottom: .25rem; }
/* Contact: Reach Us details + map */
.contact-teaser{ max-width: 1100px; text-align: left; }
.contact-inner{ display: block; }
.contact-text{ max-width: 44rem; margin-bottom: 2.4rem; }
.reach{ display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: clamp(1.6rem, 5vw, 4rem); align-items: stretch; }
.reach-head{ margin: 0 0 1.2rem; font-size: 1.3rem; color: var(--ink); }
.reach-name{ margin: 0 0 1rem !important; font-size: 1.6rem; font-weight: 400; letter-spacing: .02em; color: var(--sun-orange) !important; }
.reach-list{ list-style: none; margin: 0 0 1.4rem; padding: 0; display: grid; gap: 1.2rem; }
.reach-list li{ display: flex; gap: .9rem; align-items: flex-start; line-height: 1.6; color: var(--ink); }
.reach-list svg{ flex: 0 0 1.25rem; width: 1.25rem; height: 1.25rem; margin-top: .25rem; color: var(--sun-orange); }
.reach-list a{ color: var(--ink); text-decoration: none; }
.reach-list a:hover{ text-decoration: underline; }
.reach-link{ font-weight: 600; color: var(--bronze-deep); }
.reach-map{ min-height: 22rem; border-radius: 16px; overflow: hidden; border: 1px solid var(--line); background: var(--cream-deep); }
.reach-map iframe{ width: 100%; height: 100%; min-height: 22rem; border: 0; display: block; }
@media (max-width: 800px){ .reach{ grid-template-columns: 1fr; } }
.contact-title{ white-space: nowrap; }
/* Support page */
.sup-hero{ text-align: center; padding-bottom: 1rem; }
.sup-hero h1{ font-family: 'Fraunces', serif; font-weight: 700; font-size: clamp(2rem, 5vw, 3rem); color: var(--bronze-deep); margin: .2rem 0 1rem; }
.sup-lead{ max-width: 40rem; margin: 0 auto; color: var(--ink-soft); line-height: 1.7; }
.sup-grid{ display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 1.5rem; }
.sup-card{ display: flex; flex-direction: column; align-items: center; text-align: center; gap: .5rem; padding: 1.8rem 1.2rem; background: #FFFEFA; border: 1px solid var(--line); border-radius: 16px; box-shadow: 0 14px 30px -22px rgba(54,37,8,.5); }
.sup-card h3, .sup-topic h3{ margin: .4rem 0 0; font-family: 'Fraunces', serif; font-size: 1.2rem; color: var(--bronze-deep); }
.sup-card p{ margin: 0 0 .6rem; color: var(--ink-soft); line-height: 1.55; font-size: .92rem; flex: 1; }
.sup-card a{ font-weight: 600; color: var(--bronze-deep); overflow-wrap: anywhere; }
.sup-topic-grid{ display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 1.6rem; }
.sup-topic{ padding: 1.6rem 1.6rem 1.8rem; border-top: 3px solid var(--sun-gold); display: flex; flex-direction: column; align-items: flex-start; gap: .6rem; }
.sup-topic h3{ margin: 0; font-size: 1.3rem; }
.sup-topic p{ margin: 0 0 .6rem; color: var(--ink-soft); line-height: 1.65; flex: 1; }
.sup-prepare-wrap{ display: grid; grid-template-columns: minmax(0,4fr) minmax(0,6fr); gap: clamp(1.6rem, 5vw, 4rem); align-items: start; }
.sup-check{ list-style: none; margin: 0; padding: 0; display: grid; gap: 1.1rem; }
.sup-check li{ position: relative; padding-left: 2.2rem; display: flex; flex-direction: column; gap: .15rem; }
.sup-check li::before{ content: '\2713'; position: absolute; left: 0; top: .1rem; width: 1.5rem; height: 1.5rem; border-radius: 50%; background: var(--sun-orange); color: #FFF7E4; font-size: .85rem; font-weight: 700; display: flex; align-items: center; justify-content: center; }
.sup-check b{ color: var(--bronze-deep); }
.sup-check span{ color: var(--ink-soft); font-size: .92rem; line-height: 1.55; }
.sup-safety{ margin: 2rem 0 0; padding: 1rem 1.3rem; border-left: 4px solid var(--sun-orange); background: var(--cream-deep); border-radius: 0 12px 12px 0; color: var(--ink); line-height: 1.6; }
@media (max-width: 960px){ .sup-grid{ grid-template-columns: repeat(2, minmax(0,1fr)); } }
@media (max-width: 700px){ .sup-topic-grid, .sup-prepare-wrap{ grid-template-columns: 1fr; } }
@media (max-width: 460px){ .sup-grid{ grid-template-columns: 1fr; } }
#view-guest > section.band.pg-first.sup-hero{ min-height: 0; padding-bottom: clamp(.6rem, 2vw, 1rem); }
.sup-btn{ background: transparent; color: var(--bronze-deep); border: 2px solid var(--bronze-deep); }
.sup-btn:hover{ background: var(--bronze-deep); color: #FFF7E4; }
/* Homepage additions */
.home-about-grid{ display: grid; grid-template-columns: minmax(0,6fr) minmax(0,5fr); gap: clamp(1.6rem, 5vw, 4rem); align-items: center; }
.home-about p{ color: var(--ink-soft); line-height: 1.75; margin: 0 0 1.1rem; }
.home-points{ list-style: none; margin: 0; padding: 0; display: grid; gap: 1.1rem; }
.home-points li{ padding: 1.1rem 1.3rem; background: #FFFEFA; border: 1px solid var(--line); border-left: 4px solid var(--sun-orange); border-radius: 12px; display: flex; flex-direction: column; gap: .2rem; }
.home-points b{ font-family: 'Fraunces', serif; font-size: 1.1rem; color: var(--bronze-deep); }
.home-points span{ color: var(--ink-soft); font-size: .93rem; line-height: 1.55; }
.home-svc-grid{ display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 1.8rem; }
.home-svc-grid .service-card{ cursor: default; }
.home-svc-grid .service-card:hover{ transform: none; }
.home-svc-grid .service-card .thumb{ height: 190px; padding: 0; background: #DCEFF7; }
.home-svc-grid .service-card .thumb svg{ width: 100%; height: 100%; display: block; }
.news-grid{ display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 1.8rem; }
.news-card{ display: flex; flex-direction: column; background: #FFFEFA; border: 1px solid var(--line); border-radius: 16px; overflow: hidden; text-decoration: none; color: inherit; box-shadow: 0 14px 30px -22px rgba(54,37,8,.5); transition: transform .15s ease; }
.news-card:hover{ transform: translateY(-3px); }
.news-img{ height: 170px; background: linear-gradient(135deg, #FCEBC4, #DCEFF7); }
.news-img img{ width: 100%; height: 100%; object-fit: cover; display: block; }
.news-body{ padding: 1.2rem 1.3rem 1.4rem; display: flex; flex-direction: column; gap: .5rem; flex: 1; }
.news-body h3{ margin: 0; font-family: 'Fraunces', serif; font-size: 1.15rem; line-height: 1.3; color: var(--bronze-deep); }
.news-body p{ margin: 0; color: var(--ink-soft); font-size: .92rem; line-height: 1.55; }
.news-meta{ font-size: .8rem !important; }
.news-tag{ display: inline-block; padding: .1rem .55rem; margin-right: .4rem; border-radius: 999px; background: var(--cream-deep); color: var(--bronze-deep); font-weight: 600; }
.news-more{ margin-top: auto; font-weight: 600; color: var(--sun-orange); }
.home-more{ margin: 1.4rem 0 0; text-align: center; }
.home-more a{ font-weight: 600; color: var(--bronze-deep); }
.login-grid{ display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 1.8rem; max-width: 46rem; margin: 0 auto; }
.login-card{ display: flex; flex-direction: column; align-items: center; text-align: center; gap: .5rem; padding: 1.8rem 1.4rem; background: #FFFEFA; border: 1px solid var(--line); border-radius: 16px; }
.login-card h3{ margin: .3rem 0 0; font-family: 'Fraunces', serif; font-size: 1.25rem; color: var(--bronze-deep); }
.login-card p{ margin: 0 0 .8rem; color: var(--ink-soft); line-height: 1.55; font-size: .93rem; flex: 1; }
.login-note{ text-align: center; margin: 1.4rem 0 0; color: var(--ink-soft); }
.login-note a{ font-weight: 600; color: var(--bronze-deep); }
@media (max-width: 900px){ .home-about-grid{ grid-template-columns: 1fr; } .home-svc-grid, .news-grid{ grid-template-columns: 1fr 1fr; } }
@media (max-width: 620px){ .home-svc-grid, .news-grid, .login-grid{ grid-template-columns: 1fr; } }
</style>
</head>
<body>

<header class="site-header">
  <button class="brand-mark" id="brandLink" aria-label="Sun Son Solar Home">
    <img class="brand-logo" data-logo alt="Sun Son Solar logo">
    <span class="brand-text"><b>Sun Son Solar</b></span>
  </button>

  <button class="nav-toggle-btn" id="navToggle" aria-label="Toggle menu" aria-expanded="false">
    <svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/></svg>
  </button>

  <nav class="main-nav" id="mainNav">
    <a href="#/home" data-page-link="home">Home</a>
    <a href="#/about" data-page-link="about">About Us</a>
    <a href="#/blog" data-page-link="blog">News</a>
    <a href="#/products" data-page-link="products">Products</a>
    <a href="#/services" data-page-link="services">Services</a>
    <a href="#/projects" data-page-link="projects">Projects</a>
    <a href="#/support" data-page-link="support">Support</a>
    <a href="#/contact" data-page-link="contact">Contact Us</a>
    <a href="#" id="navOrders" class="hidden" data-goto="account">My Account</a>
    <a href="#" id="navAdmin" class="hidden" data-goto="admin">Admin panel</a>
    <a href="#" id="navTech" class="hidden" data-goto="tech">Technician portal</a>
    <a href="#" class="login-link" id="navAuth" data-goto="login">Log In</a>
  </nav>
</header>

<main>

  <section class="view" id="view-guest">
    <div id="top"></div>

    <section class="band hero-band" id="top-hero" data-page="home">
      <div class="wrap hero">
        <div class="hero-text">
          <p class="about-eyebrow">Solar for homes &amp; businesses in the Philippines</p>
          <h1>Power Your Future with Solar</h1>
          <p>Cut your electricity bill with clean power from your own roof. Sun Son Solar designs, installs, and maintains your system, from your first free consultation to long-term care.</p>
          <div class="hero-actions">
            <button type="button" class="btn btn-primary" data-quote="consultation">Get a free quote</button>
            <a href="#/products" class="btn btn-ghost jump">Explore products</a>
          </div>
          <ul class="hero-chips" aria-label="Why choose us">
            <li>25+ years of experience</li><li>Free site visit</li><li>Install, repair &amp; monitoring</li>
          </ul>
        </div>
        <div class="hero-art"><div class="hero-photo" id="heroSlider">
            <div class="hero-track" id="heroTrack">
              <img class="hero-slide" src="https://commons.wikimedia.org/wiki/Special:FilePath/Solar_Energy_Roof_Solar_Power_Generation_2666770_CC0.jpg?width=1000" alt="Rows of solar panels on a rooftop under a blue sky" width="1000" height="667" fetchpriority="high">
              <img class="hero-slide" src="https://www.unsustainablemagazine.com/wp-content/uploads/2024/11/american-public-power-association-513dBrMJ_5w-unsplash-1024x682.jpg.webp" alt="Solar panels on a rooftop" width="1024" height="682">
              <img class="hero-slide" src="https://images.pexels.com/photos/34680717/pexels-photo-34680717/free-photo-of-solar-panel-array-in-uberlandia-brazil.jpeg" alt="Solar panel array in Uberlandia, Brazil" width="1000" height="667">
            </div>
          </div></div>
      </div>
    </section>

    <section class="band home-paths" id="start" data-page="home">
      <div class="wrap">
        <h2 class="section-title">How can we help you today?</h2>
        <div class="path-grid">
          <button type="button" class="path-card" data-quote="consultation"><span class="mvv-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 11l9-8 9 8"/><path d="M5 10v10h14V10M10 20v-6h4v6"/></svg></span><b>I want solar for my home</b><span>Free site visit and a quote sized to your bills.</span><em>Start with a free quote &rarr;</em></button>
          <button type="button" class="path-card" data-quote="consultation"><span class="mvv-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h3M13 7h3M8 11h3M13 11h3M10 21v-5h4v5"/></svg></span><b>I need power for my business</b><span>Systems for shops, offices, and warehouses.</span><em>Request a business quote &rarr;</em></button>
          <button type="button" class="path-card" data-goto="login"><span class="mvv-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 3.500-7 8-7s8 3 8 7"/></svg></span><b>I'm already a customer</b><span>Log in to book maintenance, repairs, or check your account.</span><em>Log in &rarr;</em></button>
        </div>
      </div>
    </section>

    <section class="band home-about" id="who-we-are" data-page="home">
      <div class="wrap home-about-grid">
        <div>
          <p class="about-eyebrow">Who we are</p>
          <h2 class="section-title" style="text-align:left;margin-bottom:1rem">A family-run solar company you can trust</h2>
          <p>Sun Son Solar has been growing under the Philippine sun for more than 25 years. We sell panels, inverters, batteries, racking and wiring, and we handle consultation, design, permitting, installation, maintenance, repair and monitoring, so one team looks after your system from the first site visit onward.</p>
          <p>Electricity is a basic part of modern life. Our promise is to help you keep the lights on, at any time of day, with clean power from your own roof.</p>
          <a href="#/about" class="btn btn-ghost jump">Learn more about us</a>
        </div>
        <ul class="home-points">
          <li><b>Free site visit</b><span>We check your roof and review your bills before recommending anything.</span></li>
          <li><b>One team, start to finish</b><span>From design and permits to installation and long-term care.</span></li>
          <li><b>Built to last</b><span>Quality products, trained technicians, and support when you need it.</span></li>
        </ul>
      </div>
    </section>

    <section class="band benefits" id="benefits" data-page="home">
      <div class="wrap">
        <h2 class="section-title">Why switch to solar?</h2>
        <div class="benefit-grid">
          <div class="benefit"><h3>Lower electricity bills</h3><p>Make power on your own roof and buy less from the grid. We size every system to your real bills, so the savings match how you use energy.</p></div>
          <div class="benefit"><h3>Cleaner energy</h3><p>Solar panels make electricity without burning fuel. Your home or business runs on a source that adds no emissions while it works.</p></div>
          <div class="benefit"><h3>Energy independence</h3><p>Generate your own power, add a battery for outages, and worry less about changes in electricity rates.</p></div>
        </div>
      </div>
    </section>

    <section class="band home-services" id="home-services" data-page="home">
      <div class="wrap">
        <h2 class="section-title">Our main services</h2>
        <div class="home-svc-grid">
          <article class="service-card svc-info"><div class="thumb svc-consultation" aria-hidden="true"><svg viewBox="0 0 300 170" preserveAspectRatio="xMidYMid slice" role="img" aria-label="consultation illustration"><defs><linearGradient id="sky1" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#BFE3F5"/><stop offset="1" stop-color="#FDF1CF"/></linearGradient></defs><rect width="300" height="170" fill="url(#sky1)"/><circle cx="250" cy="36" r="18" fill="#F5A93B"/><circle cx="250" cy="36" r="26" fill="#F5A93B" opacity=".25"/><rect y="140" width="300" height="30" fill="#8FBF73"/><rect x="30" y="80" width="120" height="60" fill="#F3E3BE"/><polygon points="20,82 90.0,50 160,82" fill="#B5543A"/><rect x="80.0" y="125" width="20" height="15" fill="#7A4A2A"/><g transform="translate(55 38) rotate(-18)"><rect x="0" y="0" width="22" height="14" rx="1.5" fill="#1F3F5C" stroke="#9FB8CC" stroke-width="1"/><path d="M7.3 0v14M14.7 0v14M0 7.0h22" stroke="#4F7FA6" stroke-width=".7"/><rect x="25" y="0" width="22" height="14" rx="1.5" fill="#1F3F5C" stroke="#9FB8CC" stroke-width="1"/><path d="M32.3 0v14M39.7 0v14M25 7.0h22" stroke="#4F7FA6" stroke-width=".7"/><rect x="0" y="17" width="22" height="14" rx="1.5" fill="#1F3F5C" stroke="#9FB8CC" stroke-width="1"/><path d="M7.3 17v14M14.7 17v14M0 24.0h22" stroke="#4F7FA6" stroke-width=".7"/><rect x="25" y="17" width="22" height="14" rx="1.5" fill="#1F3F5C" stroke="#9FB8CC" stroke-width="1"/><path d="M32.3 17v14M39.7 17v14M25 24.0h22" stroke="#4F7FA6" stroke-width=".7"/></g><g transform="translate(190 84) scale(1 1)"><rect x="-9" y="14" width="18" height="26" rx="5" fill="#3E86AC"/><rect x="-8" y="38" width="7" height="22" rx="2" fill="#3B4A5A"/><rect x="1" y="38" width="7" height="22" rx="2" fill="#3B4A5A"/><circle cx="0" cy="6" r="8" fill="#E9B98F"/><path d="M-9 5a9 9 0 0 1 18 0z" fill="#F5C518"/><rect x="-10" y="4" width="20" height="3" rx="1.5" fill="#E0AC10"/></g><rect x="206" y="108" width="22" height="28" rx="2" fill="#fff" s