  <section class="view form-side hidden" id="view-register">
    <div class="form-wrap" id="formWrapRegister">
      <div class="form-head">
        <h2>Create your customer account</h2>
        <p>Create an account to request a free quote and track your orders. Employee accounts are created by HR or the administrators.</p>
      </div>

      <form id="regForm" novalidate>

        <div class="section">
          <h3>Personal details</h3>
          <div class="row-3">
            <div class="field" id="f-reg-first">
              <label for="regFirstName">First name</label>
              <input type="text" id="regFirstName" name="firstName" autocomplete="given-name" required>
              <div class="error-msg"></div>
            </div>
            <div class="field" id="f-reg-middle">
              <label for="regMiddleName">Middle name <span class="hint" style="display:inline">(optional)</span></label>
              <input type="text" id="regMiddleName" name="middleName" autocomplete="additional-name">
            </div>
            <div class="field" id="f-reg-last">
              <label for="regLastName">Last name</label>
              <input type="text" id="regLastName" name="lastName" autocomplete="family-name" required>
              <div class="error-msg"></div>
            </div>
          </div>
          <div class="row" style="margin-top:1.05rem">
            <div class="field" id="f-reg-birthdate">
              <label for="regBirthdate">Birthdate</label>
              <input type="date" id="regBirthdate" name="birthdate" autocomplete="bday" required>
              <div class="error-msg"></div>
            </div>
            <div class="field" id="f-reg-gender">
              <label for="regGender">Gender</label>
              <select id="regGender" name="gender" required>
                <option value="" selected disabled>Select one</option>
                <option value="female">Female</option>
                <option value="male">Male</option>
                <option value="not-say">Prefer not to say</option>
              </select>
              <div class="error-msg"></div>
            </div>
          </div>
        </div>

        <div class="section">
          <h3>Contact details</h3>
          <div class="row-3">
            <div class="field" id="f-reg-email">
              <label for="regEmail">Email address</label>
              <input type="email" id="regEmail" name="email" placeholder="johndoe@email.com" autocomplete="email" required>
              <div class="error-msg"></div>
            </div>
            <div class="field" id="f-reg-phone">
              <label for="regPhone">Phone number</label>
              <input type="tel" id="regPhone" name="phone" placeholder="09123456789" autocomplete="tel" required>
              <div class="error-msg"></div>
            </div>
            <div class="field" id="f-reg-address">
              <label for="regAddress">Address</label>
              <input type="text" id="regAddress" name="address" placeholder="Street, City, ZIP" autocomplete="street-address" required>
              <div class="error-msg"></div>
            </div>
          </div>
        </div>

        <div class="section">
          <h3>Account credentials</h3>
          <div class="row-3">
            <div class="field" id="f-reg-username">
              <label for="regUsername">Username</label>
              <input type="text" id="regUsername" name="username" autocomplete="username" required>
              <div class="error-msg"></div>
            </div>
            <div class="field" id="f-reg-pass">
              <label for="regPassword">Password</label>
              <input type="password" id="regPassword" name="password" autocomplete="new-password" required minlength="8">
              <div class="error-msg"></div>
            </div>
            <div class="field" id="f-reg-pass2">
              <label for="regConfirm">Confirm password</label>
              <input type="password" id="regConfirm" name="confirm" autocomplete="new-password" required>
              <div class="error-msg"></div>
            </div>
          </div>
        </div>

        <label class="terms">
          <input type="checkbox" id="regTerms" name="terms" required>
          <span>I agree to the <a href="#" data-legal="terms">Terms of Service</a> and <a href="#" data-legal="privacy">Privacy Policy</a>.</span>
        </label>

        <button type="submit" class="submit">Create account</button>
      </form>

      <div class="success" id="successRegister">
        <div class="badge" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none"><path d="M4 12.5l5 5L20 6.5" stroke="#3A2408" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </div>
        <h3 id="successRegisterTitle">You're in.</h3>
        <p id="successRegisterCopy">Your account is set up. A member of our crew will reach out within one business day.</p>
        <button type="button" class="link-btn" data-goto="login">Continue to log in</button>
      </div>

      <p class="switch">Already have an account? <a href="#" data-goto="login">Log in</a></p>
    </div>
  </section>

  <section class="view account-side hidden" id="view-account">
    <div class="dash-wrap">
      <div class="form-head">
        <h2 id="acctHello">My account</h2>
        <p>Manage your visits, notifications, profile, past services, and support in one place.</p>
      </div>

      <div class="dash">
        <nav class="dash-nav" role="tablist" aria-label="Account sections">
          <button type="button" role="tab" data-tab="schedule" aria-selected="true">Schedule</button>
          <button type="button" role="tab" data-tab="notifications" aria-selected="false">Notifications <span class="count hidden" id="notesCount"></span></button>
          <button type="button" role="tab" data-tab="profile" aria-selected="false">Profile</button>
          <button type="button" role="tab" data-tab="history" aria-selected="false">History</button>
          <button type="button" role="tab" data-tab="support" aria-selected="false">Support</button>
        </nav>

        <div class="dash-main">

          <section class="dash-panel active" id="dash-schedule" role="tabpanel">
            <div class="dash-card rate-prompt hidden" id="ratePrompt"></div>
            <div class="dash-card">
              <div class="panel-head"><h3>Your visits</h3></div>
              <div class="next-visit hidden" id="nextVisit"></div>
              <div id="orderList" class="booking-list"></div>
            </div>

            <div class="dash-card">
              <div class="panel-head"><h3>Book a visit</h3></div>
              <p class="hint-block">Choose a service, a day, and a time of day. Our team confirms the exact time with you.</p>
              <form id="orderForm" novalidate>
                <div class="form-grid">
                  <div class="field" id="f-ord-service"><label for="ordService">Service</label><select id="ordService"></select><div class="error-msg"></div></div>
                  <div class="field" id="f-ord-bundle"><label for="ordBundle">Package</label><select id="ordBundle"></select><div class="error-msg"></div></div>
                  <div class="field wide" id="f-ord-address"><label for="ordAddress">Install or service address</label><input type="text" id="ordAddress" placeholder="Street, City, ZIP" autocomplete="street-address"><div class="error-msg"></div></div>
                  <div class="field" id="f-ord-date"><label for="ordDate">Preferred date</label><input type="date" id="ordDate"><div class="error-msg"></div></div>
                  <div class="field" id="f-ord-time"><label for="ordTime">Time of day</label><select id="ordTime"><option value="" selected disabled>Pick a time</option><option value="morning">Morning, 8 AM to 12 PM</option><option value="afternoon">Afternoon, 1 PM to 5 PM</option></select><div class="error-msg"></div></div>
                  <div class="field wide"><label for="ordNotes">Notes <span class="hint" style="display:inline">(optional)</span></label><input type="text" id="ordNotes" placeholder="Anything we should know?"></div>
                </div>
                <div class="order-total">Estimated total: <b id="ordTotal">&#8369;0</b></div>
                <button type="submit" class="submit">Request visit</button>
              </form>
            </div>
          </section>

          <section class="dash-panel" id="dash-notifications" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head">
                <h3>Notifications</h3>
                <button type="button" class="btn-small" id="notesRead">Mark all as read</button>
              </div>
              <p class="hint-block">Reminders, schedule changes, and offers appear here.</p>
              <div id="noteList"></div>
            </div>
          </section>

          <section class="dash-panel" id="dash-profile" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Personal details</h3></div>
              <form id="profileForm" novalidate>
                <div class="form-grid">
                  <div class="field" id="f-pf-first"><label for="pfFirst">First name</label><input type="text" id="pfFirst" autocomplete="given-name"><div class="error-msg"></div></div>
                  <div class="field" id="f-pf-last"><label for="pfLast">Last name</label><input type="text" id="pfLast" autocomplete="family-name"><div class="error-msg"></div></div>
                  <div class="field" id="f-pf-middle"><label for="pfMiddle">Middle name <span class="hint" style="display:inline">(optional)</span></label><input type="text" id="pfMiddle" autocomplete="additional-name"><div class="error-msg"></div></div>
                  <div class="field" id="f-pf-email"><label for="pfEmail">Email address</label><input type="email" id="pfEmail" autocomplete="email"><div class="error-msg"></div></div>
                  <div class="field" id="f-pf-phone"><label for="pfPhone">Phone number</label><input type="tel" id="pfPhone" autocomplete="tel"><div class="error-msg"></div></div>
                  <div class="field wide" id="f-pf-address"><label for="pfAddress">Address</label><input type="text" id="pfAddress" autocomplete="street-address"><div class="error-msg"></div></div>
                </div>
                <p class="status-line" id="pfStatus" role="status"></p>
                <button type="submit" class="submit">Save changes</button>
              </form>

              <div class="sub-head"><h3>Preferences</h3></div>
              <form id="prefForm" novalidate>
                <label class="toggle-row"><input type="checkbox" id="prefRemindEmail" checked><span>Email me visit reminders</span></label>
                <label class="toggle-row"><input type="checkbox" id="prefRemindText"><span>Text me visit reminders</span></label>
                <label class="toggle-row"><input type="checkbox" id="prefPromos"><span>Send me offers and promotions</span></label>
                <p class="status-line" id="prefStatus" role="status"></p>
                <button type="submit" class="submit">Save preferences</button>
              </form>

              <div class="sub-head"><h3>Change password</h3></div>
              <form id="passwordForm" novalidate>
                <div class="field" id="f-cp-current"><label for="cpCurrent">Current password</label><input type="password" id="cpCurrent" autocomplete="current-password"><div class="error-msg"></div></div>
                <div class="form-grid">
                  <div class="field" id="f-cp-pass"><label for="cpNew">New password</label><input type="password" id="cpNew" autocomplete="new-password" minlength="8"><div class="error-msg"></div></div>
                  <div class="field" id="f-cp-pass2"><label for="cpConfirm">Confirm new password</label><input type="password" id="cpConfirm" autocomplete="new-password"><div class="error-msg"></div></div>
                </div>
                <p class="status-line" id="cpStatus" role="status"></p>
                <button type="submit" class="submit">Change password</button>
              </form>
            </div>
          </section>

          <section class="dash-panel" id="dash-history" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Past services</h3></div>
              <p class="hint-block">Completed visits appear here. Receipts are issued by our office after payment.</p>
              <div id="historyList" class="booking-list"></div>
              <div class="receipt-box hidden" id="receiptBox" tabindex="-1"></div>
            </div>
          </section>

          <section class="dash-panel" id="dash-support" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Contact our team</h3></div>
              <p class="hint-block">Send us a message and we will reply within one business day. For urgent problems, call our company line (number to be confirmed) during office hours, Monday to Saturday, 8 AM to 5 PM.</p>
              <form id="ticketForm" novalidate>
                <div class="form-grid">
                  <div class="field" id="f-tk-category"><label for="tkCategory">What is it about?</label><select id="tkCategory"><option value="" selected disabled>Select one</option><option>Booking or schedule</option><option>Billing or receipts</option><option>Service problem</option><option>Account or profile</option><option>Something else</option></select><div class="error-msg"></div></div>
                  <div class="field" id="f-tk-subject"><label for="tkSubject">Subject</label><input type="text" id="tkSubject" maxlength="120"><div class="error-msg"></div></div>
                  <div class="field wide" id="f-tk-message"><label for="tkMessage">Message</label><textarea id="tkMessage" rows="4" maxlength="2000"></textarea><div class="error-msg"></div></div>
                </div>
                <button type="submit" class="submit">Send message</button>
              </form>
            </div>
            <div class="dash-card">
              <div class="panel-head"><h3>Your messages</h3></div>
              <div id="ticketList"></div>
            </div>
          </section>

        </div>
      </div>
    </div>
  </section>

  <section class="view account-side hidden" id="view-admin">
    <div class="dash-wrap">
      <div class="form-head">
        <h2>Admin panel</h2>
        <p>Manage staff, bookings, reports, alerts, and services.</p>
      </div>

      <div class="dash">
        <nav class="dash-nav admin-nav" role="tablist" aria-label="Admin sections">
          <button type="button" role="tab" data-atab="users" aria-selected="true">Users</button>
          <button type="button" role="tab" data-atab="schedule" aria-selected="false">Schedule</button>
          <button type="button" role="tab" data-atab="reports" aria-selected="false">Reports</button>
          <button type="button" role="tab" data-atab="notifications" aria-selected="false">Notifications</button>
          <button type="button" role="tab" data-atab="settings" aria-selected="false">Settings</button>
          <button type="button" role="tab" data-atab="quotes" aria-selected="false">Quotes</button>
          <button type="button" role="tab" data-atab="problems" aria-selected="false">Problem reports <span class="count hidden" id="reportCount"></span></button>
        </nav>

        <div class="dash-main">

          <section class="admin-panel active" id="adash-users" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Add a staff account</h3></div>
              <p class="admin-note">Only HR and administrators create staff accounts. Share the username and temporary password with the new user in person or through a secure channel.</p>
              <form id="admForm" novalidate>
                <div class="section">
                  <h3>Account type</h3>
                  <div class="role-toggle">
                    <input type="radio" id="admRoleEmployee" name="admRole" value="employee" checked>
                    <label for="admRoleEmployee"><b>Employee</b><span>Office or field staff</span></label>
                    <input type="radio" id="admRoleAdmin" name="admRole" value="admin">
                    <label for="admRoleAdmin"><b>Administrator</b><span>Full access to this panel</span></label>
                  </div>
                  <div class="field dept-field open" id="f-adm-dept">
                    <label for="admDept">Department</label>
                    <select id="admDept">
                      <option value="" selected disabled>Select a department</option>
                      <option>Administration</option>
                      <option>IT</option>
                      <option>Dispatch</option>
                      <option>Accounting</option>
                      <option>HR</option>
                      <option>Marketing</option>
                      <option>Sales</option>
                      <option>Customer Service</option>
                    </select>
                    <div class="error-msg"></div>
                  </div>
                </div>

                <div class="section">
                  <h3>Personal details</h3>
                  <div class="form-grid">
                    <div class="field" id="f-adm-first"><label for="admFirst">First name</label><input type="text" id="admFirst"><div class="error-msg"></div></div>
                    <div class="field" id="f-adm-last"><label for="admLast">Last name</label><input type="text" id="admLast"><div class="error-msg"></div></div>
                    <div class="field" id="f-adm-middle"><label for="admMiddle">Middle name</label><input type="text" id="admMiddle"><div class="error-msg"></div></div>
                    <div class="field" id="f-adm-birthdate"><label for="admBirthdate">Birthdate</label><input type="date" id="admBirthdate"><div class="error-msg"></div></div>
                    <div class="field" id="f-adm-gender"><label for="admGender">Gender</label><select id="admGender"><option value="" selected disabled>Select one</option><option value="female">Female</option><option value="male">Male</option><option value="not-say">Prefer not to say</option></select><div class="error-msg"></div></div>
                  </div>
                </div>

                <div class="section">
                  <h3>Contact details</h3>
                  <div class="form-grid">
                    <div class="field" id="f-adm-email"><label for="admEmail">Email address</label><input type="email" id="admEmail" placeholder="johndoe@email.com"><div class="error-msg"></div></div>
                    <div class="field" id="f-adm-phone"><label for="admPhone">Phone number</label><input type="tel" id="admPhone" placeholder="09123456789"><div class="error-msg"></div></div>
                    <div class="field wide" id="f-adm-address"><label for="admAddress">Address</label><input type="text" id="admAddress" placeholder="Street, City, ZIP"><div class="error-msg"></div></div>
                  </div>
                </div>

                <div class="section">
                  <h3>Account credentials</h3>
                  <div class="form-grid">
                    <div class="field" id="f-adm-username"><label for="admUsername">Username</label><input type="text" id="admUsername" autocomplete="off"><div class="error-msg"></div></div>
                    <div class="field" id="f-adm-pass"><label for="admPassword">Temporary password</label><input type="password" id="admPassword" autocomplete="new-password" minlength="8"><div class="error-msg"></div></div>
                    <div class="field" id="f-adm-pass2"><label for="admConfirm">Confirm password</label><input type="password" id="admConfirm" autocomplete="new-password"><div class="error-msg"></div></div>
                  </div>
                </div>

                <p class="status-line" id="admStatus" role="status"></p>
                <button type="submit" class="submit">Create account</button>
              </form>
            </div>

            <div class="dash-card">
              <div class="panel-head"><h3>Staff accounts</h3><span class="hint" id="staffCount"></span></div>
              <div id="staffList" class="booking-list"></div>
            </div>
          </section>

          <section class="admin-panel" id="adash-schedule" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Calendar</h3></div>
              <div class="cal-head">
                <button type="button" class="btn-small" id="calPrev" aria-label="Previous month">&larr; Prev</button>
                <b id="calTitle"></b>
                <button type="button" class="btn-small" id="calNext" aria-label="Next month">Next &rarr;</button>
              </div>
              <div class="cal-grid" id="calGrid"></div>
            </div>
            <div class="dash-card">
              <div class="panel-head"><h3 id="agendaTitle">Bookings</h3></div>
              <div id="agendaList" class="booking-list"></div>
            </div>
            <div class="dash-card">
              <div class="panel-head"><h3>Technician availability</h3></div>
              <p class="hint-block">The next 7 days. Tap a day to mark a technician off, and tap again to make them available. Busy days show how many jobs are assigned.</p>
              <div id="availGrid"></div>
            </div>
          </section>

          <section class="admin-panel" id="adash-reports" role="tabpanel">
            <div class="stat-grid">
              <div class="stat"><b id="stCustomers">0</b><span>Customers with bookings</span></div>
              <div class="stat"><b id="stBookings">0</b><span>Active bookings</span></div>
              <div class="stat"><b id="stCompleted">0</b><span>Completed visits</span></div>
              <div class="stat"><b id="stRevenue">&#8369;0</b><span>Revenue from completed visits</span></div>
              <div class="stat"><b id="stRating">–</b><span>Average customer rating</span></div>
            </div>
            <div class="chart-grid">
              <div class="dash-card"><div class="panel-head"><h3>Bookings by service</h3></div><div id="chartService"></div></div>
              <div class="dash-card"><div class="panel-head"><h3>Booking status</h3></div><div id="chartStatus"></div></div>
              <div class="dash-card"><div class="panel-head"><h3>Revenue by visit month</h3></div><div id="chartRevenue"></div></div>
            </div>
            <p class="hint-block">Figures come from bookings saved in this browser. Revenue counts visits marked as completed.</p>
          </section>

          <section class="admin-panel" id="adash-notifications" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Which alerts go out</h3></div>
              <p class="hint-block">Turn off an alert type to stop it from reaching customers. Booking confirmations and schedule changes always go out.</p>
              <form id="nfForm" novalidate>
                <label class="toggle-row"><input type="checkbox" id="nfReminders" checked><span>Visit reminders</span></label>
                <label class="toggle-row"><input type="checkbox" id="nfPromos" checked><span>Promotions and offers</span></label>
                <label class="toggle-row"><input type="checkbox" id="nfSystem" checked><span>System updates</span></label>
                <p class="status-line" id="nfStatus" role="status"></p>
                <button type="submit" class="submit">Save alert settings</button>
              </form>
            </div>
            <div class="dash-card">
              <div class="panel-head"><h3>Send an alert</h3></div>
              <p class="hint-block" id="sendAudience"></p>
              <form id="sendForm" novalidate>
                <div class="field" id="f-send-type"><label for="sendType">Alert type</label>
                  <select id="sendType"><option value="Promotion">Promotion or offer</option><option value="System update">System update</option></select>
                  <div class="error-msg"></div>
                </div>
                <div class="field" id="f-send-text"><label for="sendText">Message</label>
                  <textarea id="sendText" rows="3" maxlength="400" placeholder="Example: Panel cleaning is 20 percent off this month."></textarea>
                  <div class="error-msg"></div>
                </div>
                <p class="status-line" id="sendStatus" role="status"></p>
                <button type="submit" class="submit">Send alert</button>
              </form>
            </div>
            <div class="dash-card">
              <div class="panel-head"><h3>Announce to technicians</h3></div>
              <p class="hint-block">Safety guidelines, urgent notices, and general messages appear in every technician's portal.</p>
              <form id="annForm" novalidate>
                <div class="field"><label for="annKind">Kind of message</label><select id="annKind"><option>General message</option><option>Safety guideline</option><option>Urgent notice</option></select></div>
                <div class="field" id="f-ann-text"><label for="annText">Message</label><textarea id="annText" rows="3" maxlength="500"></textarea><div class="error-msg"></div></div>
                <p class="status-line" id="annStatus" role="status"></p>
                <button type="submit" class="submit">Post announcement</button>
              </form>
              <div class="sub-head"><h3>Recently posted</h3></div>
              <div id="annAdminList" class="admin-ann-list"></div>
            </div>
          </section>

          <section class="admin-panel" id="adash-settings" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Services and prices</h3></div>
              <p class="hint-block">Turn a service or package off to hide it from customers, or change its price in pesos.</p>
              <div id="svcSettings"></div>
            </div>
            <div class="dash-card">
              <div class="panel-head"><h3>Service categories</h3></div>
              <p class="hint-block">Add a new kind of service. Each package goes on its own line as: Name | price in pesos | short description.</p>
              <div id="customList"></div>
              <div class="sub-head"><h3>Add a category</h3></div>
              <form id="catAddForm" novalidate>
                <div class="form-grid">
                  <div class="field" id="f-cat-name"><label for="catName">Category name</label><input type="text" id="catName" maxlength="60"><div class="error-msg"></div></div>
                  <div class="field" id="f-cat-desc"><label for="catDesc">Short description</label><input type="text" id="catDesc" maxlength="200"><div class="error-msg"></div></div>
                  <div class="field wide" id="f-cat-pkgs"><label for="catPkgs">Packages</label><textarea id="catPkgs" rows="4" placeholder="Basic Check | 2500 | One-hour inspection"></textarea><div class="error-msg"></div></div>
                </div>
                <p class="status-line" id="catAddStatus" role="status"></p>
                <button type="submit" class="submit">Add category</button>
              </form>
            </div>
            <div class="dash-card">
              <div class="panel-head"><h3>Availability</h3></div>
              <p class="hint-block">Choose the days customers can book and the times of day offered.</p>
              <div class="avail-grid">
                <div>
                  <span class="avail-label">Open days</span>
                  <div class="day-picks">
                    <label class="chip-check"><input type="checkbox" id="day1"><span>Mon</span></label>
                    <label class="chip-check"><input type="checkbox" id="day2"><span>Tue</span></label>
                    <label class="chip-check"><input type="checkbox" id="day3"><span>Wed</span></label>
                    <label class="chip-check"><input type="checkbox" id="day4"><span>Thu</span></label>
                    <label class="chip-check"><input type="checkbox" id="day5"><span>Fri</span></label>
                    <label class="chip-check"><input type="checkbox" id="day6"><span>Sat</span></label>
                    <label class="chip-check"><input type="checkbox" id="day0"><span>Sun</span></label>
                  </div>
                </div>
                <div>
                  <span class="avail-label">Time of day</span>
                  <label class="toggle-row"><input type="checkbox" id="slotMorning" checked><span>Morning, 8 AM to 12 PM</span></label>
                  <label class="toggle-row"><input type="checkbox" id="slotAfternoon" checked><span>Afternoon, 1 PM to 5 PM</span></label>
                </div>
              </div>
            </div>
            <div class="dash-card">
              <p class="status-line" id="catStatus" role="status"></p>
              <button type="button" class="submit" id="catSave">Save settings</button>
            </div>
            <div class="dash-card">
              <div class="panel-head"><h3>Recent admin changes</h3></div>
              <p class="hint-block">Staff, booking, price, alert, and announcement changes are logged here.</p>
              <div id="auditList"></div>
            </div>
          </section>

          <section class="admin-panel" id="adash-quotes" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Quote requests</h3></div>
              <p class="hint-block">Requests from the public quote form. Update the status as you contact each customer.</p>
              <div id="quoteList" class="booking-list"></div>
            </div>
          </section>

          <section class="admin-panel" id="adash-problems" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Problem reports</h3></div>
              <p class="hint-block">Reports that technicians send from the field appear here, newest first.</p>
              <div id="reportList" class="booking-list"></div>
            </div>
          </section>

        </div>
      </div>
    </div>
  </section>

  <section class="view account-side hidden" id="view-tech">
    <div class="dash-wrap">
      <div class="form-head">
        <h2>Technician portal</h2>
        <p>Check in on site, see your jobs, read announcements, and report problems.</p>
      </div>

      <div class="dash">
        <nav class="dash-nav tech-nav" role="tablist" aria-label="Technician sections">
          <button type="button" role="tab" data-ttab="checkin" aria-selected="true">Check in</button>
          <button type="button" role="tab" data-ttab="jobs" aria-selected="false">My jobs</button>
          <button type="button" role="tab" data-ttab="announcements" aria-selected="false">Announcements <span class="count hidden" id="annCount"></span></button>
          <button type="button" role="tab" data-ttab="report" aria-selected="false">Report a problem</button>
        </nav>

        <div class="dash-main">

          <section class="tech-panel active" id="tdash-checkin" role="tabpanel">
            <div class="dash-card checkin-card">
              <p class="checkin-lead">Tap the button when you arrive on site.</p>
              <button type="button" class="checkin-btn" id="checkinBtn">Check in</button>
              <p class="checkin-status" id="checkinStatus" role="status" aria-live="polite"></p>
            </div>
            <div class="dash-card">
              <div class="panel-head"><h3>Your recent check-ins</h3></div>
              <div id="checkinList"></div>
            </div>
          </section>

          <section class="tech-panel" id="tdash-jobs" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Assigned jobs</h3></div>
              <p class="hint-block">Only jobs assigned to you appear here. You see only the customer name, address, and service.</p>
              <div id="jobList" class="booking-list"></div>
            </div>
          </section>

          <section class="tech-panel" id="tdash-announcements" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Announcements</h3></div>
              <p class="hint-block">Messages from administrators and HR, including safety guidelines and urgent notices.</p>
              <div id="annList"></div>
            </div>
          </section>

          <section class="tech-panel" id="tdash-report" role="tabpanel">
            <div class="dash-card">
              <div class="panel-head"><h3>Report a problem</h3></div>
              <p class="hint-block">Equipment issues and customer concerns go straight to the admin panel.</p>
              <form id="reportForm" novalidate>
                <div class="form-grid">
                  <div class="field" id="f-rp-cat"><label for="rpCat">What kind of problem?</label><select id="rpCat"><option value="" selected disabled>Select one</option><option>Equipment problem</option><option>Customer concern</option><option>Safety concern</option><option>Something else</option></select><div class="error-msg"></div></div>
                  <div class="field" id="f-rp-job"><label for="rpJob">Related job</label><select id="rpJob"></select><div class="error-msg"></div></div>
                  <div class="field wide" id="f-rp-text"><label for="rpText">What happened?</label><textarea id="rpText" rows="4" maxlength="1000"></textarea><div class="error-msg"></div></div>
                </div>
                <p class="status-line" id="reportStatus" role="status"></p>
                <button type="submit" class="submit">Send report</button>
              </form>
            </div>
            <div class="dash-card">
              <div class="panel-head"><h3>Your reports</h3></div>
              <div id="myReports"></div>
            </div>
          </section>

        </div>
      </div>
    </div>
  </section>

  <section class="view form-side hidden" id="view-quote">
    <div class="form-wrap wide" id="formWrapQuote">
      <div class="form-head">
        <h2>Request a free quote</h2>
        <p class="quote-intro">Tell us about your property and your power bill. We visit the site, check the roof, and send a written quote. The quote is free.</p>
      </div>

      <form id="quoteForm" novalidate>
        <div class="section">
          <h3>About you</h3>
          <div class="form-grid">
            <div class="field" id="f-q-first"><label for="qFirst">First name</label><input type="text" id="qFirst" autocomplete="given-name"><div class="error-msg"></div></div>
            <div class="field" id="f-q-last"><label for="qLast">Last name</label><input type="text" id="qLast" autocomplete="family-name"><div class="error-msg"></div></div>
            <div class="field" id="f-q-email"><label for="qEmail">Email address</label><input type="email" id="qEmail" autocomplete="email" placeholder="johndoe@email.com"><div class="error-msg"></div></div>
            <div class="field" id="f-q-phone"><label for="qPhone">Phone number</label><input type="tel" id="qPhone" autocomplete="tel" placeholder="09123456789"><div class="error-msg"></div></div>
          </div>
        </div>

        <div class="section">
          <h3>Your property</h3>
          <div class="form-grid">
            <div class="field wide" id="f-q-address"><label for="qAddress">Address of the site</label><input type="text" id="qAddress" autocomplete="street-address" placeholder="Street, City, ZIP"><div class="error-msg"></div></div>
            <div class="field" id="f-q-property"><label for="qProperty">Type of property</label>
              <select id="qProperty"><option value="" selected disabled>Select one</option><option>Home</option><option>Shop or small business</option><option>Office</option><option>Warehouse or factory</option><option>Other</option></select>
              <div class="error-msg"></div></div>
            <div class="field" id="f-q-roof"><label for="qRoof">Roof type</label>
              <select id="qRoof"><option value="" selected>Not sure</option><option>Concrete</option><option>Metal sheet</option><option>Tile</option><option>Other</option></select>
              <div class="error-msg"></div></div>
            <div class="field wide" id="f-q-bill"><label for="qBill">Average monthly electricity bill (&#8369;) <span class="hint" style="display:inline">(optional)</span></label><input type="number" id="qBill" min="0" step="100" inputmode="decimal"><div class="error-msg"></div></div>
          </div>
        </div>

        <div class="section">
          <h3>What you need</h3>
          <div class="form-grid">
            <div class="field" id="f-q-service"><label for="qService">Service</label>
              <select id="qService"><option value="" selected disabled>Select one</option><option>Consultation</option><option>Designing</option><option>Permitting</option><option>Installation</option><option>Maintenance</option><option>Repair</option><option>Monitoring</option><option>Products only</option><option>Not sure yet</option></select>
              <div class="error-msg"></div></div>
            <div class="field" id="f-q-battery"><label for="qBattery">Do you want a battery backup?</label>
              <select id="qBattery"><option value="Not sure">Not sure</option><option value="Yes">Yes</option><option value="No">No</option></select>
              <div class="error-msg"></div></div>
            <div class="field" id="f-q-contact"><label for="qContact">How should we reach you?</label>
              <select id="qContact"><option value="Call">Call me</option><option value="Text">Text me</option><option value="Email">Email me</option></select>
              <div class="error-msg"></div></div>
            <div class="field wide" id="f-q-notes"><label for="qNotes">Anything else? <span class="hint" style="display:inline">(optional)</span></label><textarea id="qNotes" rows="3" maxlength="800"></textarea><div class="error-msg"></div></div>
          </div>
        </div>

        <p class="status-line" id="qStatus" role="status"></p>
        <button type="submit" class="submit">Send quote request</button>
      </form>

      <div class="success" id="successQuote">
        <div class="badge" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none"><path d="M4 12.5l5 5L20 6.5" stroke="#3A2408" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </div>
        <h3>Request received.</h3>
        <p>Your reference is <b id="qRef"></b>. A member of our team will contact you within one business day.</p>
        <button type="button" class="link-btn" data-goto="guest">Back to home</button>
      </div>
    </div>
  </section>

  <section class="view form-side hidden" id="view-reset">
    <div class="form-wrap" id="formWrapReset">
      <div class="form-head">
        <h2>Reset your password</h2>
        <p id="resetLead">Enter the email address on your account. We will send a six-digit code.</p>
      </div>

      <form id="resetRequestForm" novalidate>
        <div class="field" id="f-rs-email"><label for="rsEmail">Email address</label><input type="email" id="rsEmail" autocomplete="email"><div class="error-msg"></div></div>
        <p class="status-line" id="rsStatus" role="status"></p>
        <button type="submit" class="submit">Send code</button>
      </form>

      <form id="resetConfirmForm" class="hidden" novalidate>
        <div class="field" id="f-rc-code"><label for="rcCode">Six-digit code</label><input type="text" id="rcCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code"><div class="error-msg"></div></div>
        <div class="field" id="f-rc-pass"><label for="rcPass">New password</label><input type="password" id="rcPass" autocomplete="new-password" minlength="8"><div class="error-msg"></div></div>
        <div class="field" id="f-rc-pass2"><label for="rcPass2">Confirm new password</label><input type="password" id="rcPass2" autocomplete="new-password"><div class="error-msg"></div></div>
        <p class="status-line" id="rcStatus" role="status"></p>
        <button type="submit" class="submit">Set new password</button>
      </form>

      <div class="success" id="successReset">
        <div class="badge" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none"><path d="M4 12.5l5 5L20 6.5" stroke="#3A2408" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </div>
        <h3>Password changed.</h3>
        <p>You can log in with your new password.</p>
        <button type="button" class="link-btn" data-goto="login">Go to log in</button>
      </div>

      <p class="switch"><a href="#" data-goto="login">Back to log in</a></p>
    </div>
  </section>

</main>

