<script>
/* Embedded logo (single copy, assigned to every logo slot) */
var LOGO_SRC = "data:image/png;base64,";
document.querySelectorAll('img[data-logo]').forEach(function(img){ img.src = LOGO_SRC; });
document.getElementById('favicon').href = LOGO_SRC;
document.getElementById('appleIcon').href = LOGO_SRC;
(function(){

    const views = {
    guest: document.getElementById('view-guest'),
    login: document.getElementById('view-login'),
    register: document.getElementById('view-register'),
    account: document.getElementById('view-account'),
    admin: document.getElementById('view-admin'),
    tech: document.getElementById('view-tech'),
    quote: document.getElementById('view-quote'),
    reset: document.getElementById('view-reset')
  };
  const footer = document.getElementById('siteFooter');

  function jumpToTop(){
    var root = document.documentElement, prev = root.style.scrollBehavior;
    root.style.scrollBehavior = 'auto';
    window.scrollTo(0, 0);
    root.style.scrollBehavior = prev;
  }

  function showView(name, opts){
    opts = opts || {};
    if(name === 'account' && !currentUser){ name = 'login'; }
    if(name === 'admin' && !isStaff()){ name = currentUser ? 'account' : 'login'; }
    if(name === 'tech' && !isTech()){ name = currentUser ? 'account' : 'login'; }
    if(name === 'account'){ renderAccount(); renderProfile(); }
    if(name === 'tech'){ renderTech(); }
    if(name === 'quote'){ renderQuote(); }
    if(name === 'reset'){ renderReset(); }
    if(name === 'admin'){ renderAdmin(); }
    Object.keys(views).forEach(function(key){
      views[key].classList.toggle('hidden', key !== name);
    });
    footer.classList.toggle('hidden', name !== 'guest');
    if(name === 'guest'){ applyPage(); } else { markActiveNav(null); }

    jumpToTop();
  }

  window.__sunSonShowView = showView;

  /* ---------- Multi-page routing (Home, About Us, Products, Services, Projects, Support, Contact Us) ---------- */
  var PAGE_TITLES = {
    home: 'Sun Son Solar', about: 'About Us | Sun Son Solar', blog: 'News | Sun Son Solar', products: 'Products | Sun Son Solar',
    services: 'Services | Sun Son Solar', projects: 'Projects | Sun Son Solar',
    support: 'Support | Sun Son Solar', contact: 'Contact Us | Sun Son Solar'
  };
  var currentPage = 'home';

  function pageFromHash(hash){
    var h = String(hash || '').replace(/^#\/?/, '');
    if(!h) return null;
    if(PAGE_TITLES[h]) return { page: h, scrollId: null };
    if(h === 'top') return { page: 'home', scrollId: null };
    var el = document.getElementById(h);
    var host = el && el.closest ? el.closest('[data-page]') : null;
    if(host) return { page: host.getAttribute('data-page').split(' ')[0], scrollId: (host === el ? null : h) };
    return null;
  }

  function markActiveNav(page){
    document.querySelectorAll('.main-nav a[data-page-link]').forEach(function(a){
      var on = page && a.getAttribute('data-page-link') === page;
      a.classList.toggle('active', !!on);
      if(on) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current');
    });
  }

  function applyPage(){
    var p = currentPage || 'home';
    var first = null;
    document.querySelectorAll('#view-guest > section[data-page]').forEach(function(s){
      var show = s.getAttribute('data-page').split(' ').indexOf(p) > -1;
      s.classList.toggle('pg-off', !show);
      s.classList.remove('pg-first');
      if(show && !first) first = s;
    });
    if(first) first.classList.add('pg-first');
    markActiveNav(p);
    document.title = PAGE_TITLES[p] || PAGE_TITLES.home;
    // carousels and the projects scroller measure themselves on resize
    window.dispatchEvent(new Event('resize'));
    if(window.__layoutProjects){ requestAnimationFrame(window.__layoutProjects); }
  }

  var pendingScroll = null;
  function routeFromHash(){
    var r = pageFromHash(location.hash);
    if(!r) return;
    currentPage = r.page;
    showView('guest');
    var id = r.scrollId || pendingScroll;
    pendingScroll = null;
    if(id){
      requestAnimationFrame(function(){
        var t = document.getElementById(id);
        if(t) t.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
    }
  }

  function goPage(page, scrollId){
    pendingScroll = scrollId || null;
    var h = '#/' + page;
    if(location.hash === h){ routeFromHash(); }
    else { location.hash = h; }
  }

  window.addEventListener('hashchange', routeFromHash);

    const navToggle = document.getElementById('navToggle');
  const mainNav = document.getElementById('mainNav');

  function closeMobileNav(){
    mainNav.classList.remove('open');
    navToggle.setAttribute('aria-expanded', 'false');
  }
  
  document.addEventListener('click', function(e){
    if(mainNav.classList.contains('open') && !mainNav.contains(e.target) && !navToggle.contains(e.target)) closeMobileNav();
  });
  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape' && mainNav.classList.contains('open')){ closeMobileNav(); navToggle.focus(); }
  });
  var desktopNav = window.matchMedia('(min-width: 961px)');
  if(desktopNav.addEventListener) desktopNav.addEventListener('change', closeMobileNav);
  else if(desktopNav.addListener) desktopNav.addListener(closeMobileNav);

  navToggle.addEventListener('click', function(){
    const open = mainNav.classList.toggle('open');
    navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  });

  document.getElementById('brandLink').addEventListener('click', function(){
    closeMobileNav();
    goPage('home');
  });

  document.querySelectorAll('.main-nav a:not([data-goto])').forEach(function(link){
    link.addEventListener('click', function(){
      closeMobileNav();
    });
  });

    document.querySelectorAll('[data-goto]').forEach(function(el){
    el.addEventListener('click', function(e){
      e.preventDefault();
      closeMobileNav();
      if(el.id === 'navAuth' && currentUser){
        api('/api/logout', 'POST').then(function(){ location.reload(); });
        return;
      }
      showView(el.getAttribute('data-goto'));
    });
  });


  var currentUser = null;
  var FIELD_MAP = {
    firstName:'f-reg-first', lastName:'f-reg-last', birthdate:'f-reg-birthdate',
    gender:'f-reg-gender', email:'f-reg-email', phone:'f-reg-phone',
    address:'f-reg-address', username:'f-reg-username', password:'f-reg-pass',
    confirm:'f-reg-pass2', department:'f-reg-dept',
    loginId:'f-login-id', loginPassword:'f-login-password'
  };

  function api(path, method, body){
    return fetch('.' + path, {
      method: method,
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: body ? JSON.stringify(body) : undefined
    }).then(function(res){
      return res.json().catch(function(){
        return { ok:false, errors:{ _form:'Unexpected server response.' } };
      }).then(function(data){ data.status = res.status; return data; });
    });
  }

  function showFormError(form, msg){
    var box = form.querySelector('.form-error');
    if(!box){
      box = document.createElement('div');
      box.className = 'error-msg form-error';
      box.setAttribute('role', 'alert');
      form.insertBefore(box, form.querySelector('button.submit'));
    }
    box.textContent = msg || '';
  }

  function applyServerErrors(form, errors){
    var shown = false;
    Object.keys(errors || {}).forEach(function(k){
      if(FIELD_MAP[k]){ setError(FIELD_MAP[k], errors[k]); }
      else { showFormError(form, errors[k]); }
      shown = true;
    });
    if(!shown) showFormError(form, 'Something went wrong. Please try again.');
  }

  function setBusy(btn, busy){
    btn.disabled = busy;
    if(busy){ btn.dataset.label = btn.textContent; btn.textContent = 'Please wait...'; }
    else if(btn.dataset.label){ btn.textContent = btn.dataset.label; }
  }

  function setUser(u){
    currentUser = u;
    var link = document.getElementById('navAuth');
    if(link) link.textContent = u ? 'Log Out' : 'Log In';
    var ord = document.getElementById('navOrders');
    if(ord) ord.classList.toggle('hidden', !u);
    var adm = document.getElementById('navAdmin');
    var canAdmin = !!(u && (u.role === 'admin' || u.role === 'hr' || isDispatcher()));
    if(adm){ adm.classList.toggle('hidden', !canAdmin); adm.textContent = isDispatchOnly() ? 'Dispatch schedule' : 'Admin panel'; }
    var tch = document.getElementById('navTech');
    if(tch) tch.classList.toggle('hidden', !(u && u.role === 'employee'));
  }

    const loginForm = document.getElementById('loginForm');
  const loginWrap = document.getElementById('formWrapLogin');
  const successLogin = document.getElementById('successLogin');

  function setError(fieldId, msg){
    const field = document.getElementById(fieldId);
    field.classList.toggle('invalid', !!msg);
    const em = field.querySelector('.error-msg');
    if(em) em.textContent = msg || '';
  }

  loginForm.addEventListener('submit', function(e){
    e.preventDefault();
    let valid = true;

    const loginId = document.getElementById('loginId').value.trim();
    setError('f-login-id', loginId ? '' : 'Enter your username or email.');
    if(!loginId) valid = false;

    const loginPassword = document.getElementById('loginPassword').value;
    setError('f-login-password', loginPassword ? '' : 'Enter your password.');
    if(!loginPassword) valid = false;

    if(!valid) return;

    var btn = loginForm.querySelector('button.submit');
    showFormError(loginForm, '');
    setBusy(btn, true);
    api('/api/login', 'POST', {
      loginId: loginId,
      loginPassword: loginPassword,
      remember: document.getElementById('remember').checked
    }).then(function(data){
      if(!data.ok){ applyServerErrors(loginForm, data.errors); return; }
      setUser(data);
      setTimeout(function(){ if(currentUser) showView('account'); }, 1200);
      document.getElementById('successLoginCopy').textContent =
        'Welcome back, ' + data.firstName + '. Taking you to your account\u2026';
      loginWrap.classList.add('done');
      successLogin.classList.add('show');
      successLogin.setAttribute('tabindex', '-1');
      successLogin.focus();
    }).catch(function(){
      showFormError(loginForm, 'Cannot reach the server. Check your connection and try again.');
    }).then(function(){ setBusy(btn, false); });
  });

    const regForm = document.getElementById('regForm');
  const regWrap = document.getElementById('formWrapRegister');
  const successRegister = document.getElementById('successRegister');

  function requireText(id, fieldId, msg){
    const v = document.getElementById(id).value.trim();
    setError(fieldId, v ? '' : msg);
    return !!v;
  }

  regForm.addEventListener('submit', function(e){
    e.preventDefault();
    let valid = true;

    if(!requireText('regFirstName', 'f-reg-first', 'Enter your first name.')) valid = false;
    if(!requireText('regLastName', 'f-reg-last', 'Enter your last name.')) valid = false;

    const birthdate = document.getElementById('regBirthdate').value;
    setError('f-reg-birthdate', birthdate ? '' : 'Enter your birthdate.');
    if(!birthdate) valid = false;

    const gender = document.getElementById('regGender').value;
    setError('f-reg-gender', gender ? '' : 'Choose one.');
    if(!gender) valid = false;

    const email = document.getElementById('regEmail').value.trim();
    const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    setError('f-reg-email', emailOk ? '' : 'Enter a valid email.');
    if(!emailOk) valid = false;

    const phone = document.getElementById('regPhone').value.trim();
    setError('f-reg-phone', phone.length >= 7 ? '' : 'Enter a phone number.');
    if(phone.length < 7) valid = false;

    if(!requireText('regAddress', 'f-reg-address', 'Enter your address.')) valid = false;
    if(!requireText('regUsername', 'f-reg-username', 'Choose a username.')) valid = false;

    const pass = document.getElementById('regPassword').value;
    setError('f-reg-pass', pass.length >= 8 ? '' : 'At least 8 characters.');
    if(pass.length < 8) valid = false;

    const confirm = document.getElementById('regConfirm').value;
    setError('f-reg-pass2', (confirm && confirm === pass) ? '' : 'Passwords don\u2019t match.');
    if(!confirm || confirm !== pass) valid = false;


    const terms = document.getElementById('regTerms').checked;
    if(!terms){ valid = false; document.getElementById('regTerms').focus(); }

    if(!valid) return;

    var btn = regForm.querySelector('button.submit');
    showFormError(regForm, '');
    setBusy(btn, true);
    api('/api/register', 'POST', {
      firstName: document.getElementById('regFirstName').value.trim(),
      middleName: document.getElementById('regMiddleName').value.trim(),
      lastName: document.getElementById('regLastName').value.trim(),
      birthdate: birthdate,
      gender: gender,
      email: email,
      phone: phone,
      address: document.getElementById('regAddress').value.trim(),
      username: document.getElementById('regUsername').value.trim(),
      password: pass,
      confirm: confirm,
      role: 'customer',
      department: '',
      terms: terms
    }).then(function(data){
      if(!data.ok){ applyServerErrors(regForm, data.errors); return; }
      document.getElementById('successRegisterTitle').textContent = 'Welcome, ' + data.firstName + '.';
      document.getElementById('successRegisterCopy').textContent =
        'Your account is set up. Log in to request your free quote. A member of our crew will reach out within one business day.';
      regWrap.classList.add('done');
      successRegister.classList.add('show');
      successRegister.setAttribute('tabindex', '-1');
      successRegister.focus();
    }).catch(function(){
      showFormError(regForm, 'Cannot reach the server. Check your connection and try again.');
    }).then(function(){ setBusy(btn, false); });
  });

  document.querySelectorAll('.jump').forEach(function(link){
    link.addEventListener('click', function(e){
      e.preventDefault();
      var pg = pageFromHash(link.getAttribute('href'));
      if(pg) goPage(pg.page, pg.scrollId);
    });
