  /* ---------- Password reset ---------- */
  var resetEmail = '';
  function renderReset(){
    resetEmail = '';
    document.getElementById('formWrapReset').classList.remove('done');
    document.getElementById('successReset').classList.remove('show');
    document.getElementById('rsStatus').textContent = '';
    document.getElementById('rcStatus').textContent = '';
    showResetStep(1);
  }
  function showResetStep(step){
    document.getElementById('resetRequestForm').classList.toggle('hidden', step !== 1);
    document.getElementById('resetConfirmForm').classList.toggle('hidden', step !== 2);
    document.getElementById('resetLead').textContent = step === 1
      ? 'Enter the email address on your account. We will send a six-digit code.'
      : 'Enter the code we sent to ' + resetEmail + ' and choose a new password.';
  }

  document.getElementById('resetRequestForm').addEventListener('submit', function(e){
    e.preventDefault();
    var form = e.target, status = document.getElementById('rsStatus');
    var email = val('rsEmail');
    setError('f-rs-email', isEmail(email) ? '' : 'Enter a valid email.');
    if(!isEmail(email)) return;
    var btn = form.querySelector('button.submit');
    showFormError(form, ''); status.textContent = ''; setBusy(btn, true);
    api('/api/password/reset/request', 'POST', { email: email }).then(function(d){
      if(!d.ok){ applyFieldErrors(form, d.errors, 'f-rs-'); return; }
      resetEmail = email;
      status.textContent = '';
      showResetStep(2);
    }).catch(function(){
      showFormError(form, 'Cannot reach the server. Check your connection and try again.');
    }).then(function(){ setBusy(btn, false); });
  });

  document.getElementById('resetConfirmForm').addEventListener('submit', function(e){
    e.preventDefault();
    var form = e.target, status = document.getElementById('rcStatus');
    var code = val('rcCode'), pass = document.getElementById('rcPass').value, conf = document.getElementById('rcPass2').value;
    setError('f-rc-code', /^\d{6}$/.test(code) ? '' : 'Enter the six digits from the email.');
    setError('f-rc-pass', pass.length >= 8 ? '' : 'At least 8 characters.');
    setError('f-rc-pass2', (conf && conf === pass) ? '' : 'Passwords don\u2019t match.');
    if(!/^\d{6}$/.test(code) || pass.length < 8 || conf !== pass) return;
    var btn = form.querySelector('button.submit');
    showFormError(form, ''); status.textContent = ''; setBusy(btn, true);
    api('/api/password/reset/confirm', 'POST', { email: resetEmail, code: code, password: pass, confirm: conf }).then(function(d){
      if(!d.ok){ applyFieldErrors(form, d.errors, 'f-rc-'); return; }
      form.reset();
      document.getElementById('formWrapReset').classList.add('done');
      document.getElementById('successReset').classList.add('show');
      document.getElementById('successReset').setAttribute('tabindex', '-1');
      document.getElementById('successReset').focus();
    }).catch(function(){
      showFormError(form, 'Cannot reach the server. Check your connection and try again.');
    }).then(function(){ setBusy(btn, false); });
  });

  /* ---------- Online payment and receipts (customer) ---------- */
  var PAY_UNAVAILABLE = 'Online payment is not available right now. Please try again later or pay at our office.';
  function receiptNo(o){ return 'SSS-' + String(o.date || '').replace(/-/g, '') + '-' + String(o.id).slice(-4); }
  function fullName(){ return ((currentUser.firstName || '') + ' ' + (currentUser.lastName || '')).trim(); }

  function payRow(o){
    var wrap = el('div', 'pay-row');
    if(o.paid){
      wrap.appendChild(el('div', 'meta', 'Paid ' + peso(o.paidAmount) + ' by ' + String(o.paidMethod || 'cash').toLowerCase() + ' \u00B7 Receipt ' + o.receiptNo));
      var view = el('button', 'btn-small', 'View receipt'); view.type = 'button';
      view.addEventListener('click', function(){ showReceipt(o); });
      wrap.appendChild(view);
      return wrap;
    }
    if(!o.price){ wrap.appendChild(el('div', 'meta', 'No payment is needed for this visit.')); return wrap; }
    wrap.appendChild(el('div', 'meta', 'Payment due: ' + peso(o.price)));
    var pay = el('button', 'btn-small', 'Pay online'); pay.type = 'button';
    var msg = el('p', 'status-line');
    pay.addEventListener('click', function(){
      pay.disabled = true;
      msg.textContent = 'Opening secure payment\u2026';
      api('/api/payments/checkout', 'POST', { bookingId: o.id, amount: o.price }).then(function(d){
        if(d.ok && d.checkoutUrl){ window.location.href = d.checkoutUrl; return; }
        msg.textContent = PAY_UNAVAILABLE;
      }).catch(function(){
        msg.textContent = PAY_UNAVAILABLE;
      }).then(function(){ pay.disabled = false; });
    });
    wrap.appendChild(pay);
    wrap.appendChild(msg);
    return wrap;
  }

  function showReceipt(o){
    var box = document.getElementById('receiptBox');
    box.textContent = '';
    var head = el('div', 'panel-head');
    head.appendChild(el('h3', null, 'Receipt ' + o.receiptNo));
    var printBtn = el('button', 'btn-small', 'Print receipt'); printBtn.type = 'button';
    printBtn.addEventListener('click', function(){ window.print(); });
    head.appendChild(printBtn);
    box.appendChild(head);
    var paidDay = new Date(o.paidAt).toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' });
    [
      ['Company', 'Sun Son Solar'],
      ['Customer', fullName()],
      ['Service', o.service],
      ['Package', o.bundle],
      ['Visit date', fmtDate(o.date)],
      ['Amount paid', peso(o.paidAmount)],
      ['Payment method', o.paidMethod || 'Cash'],
      ['Paid on', paidDay]
    ].forEach(function(r){
      var row = el('div', 'receipt-row');
      row.appendChild(el('span', 'receipt-k', r[0]));
      row.appendChild(el('span', 'receipt-v', r[1]));
      box.appendChild(row);
    });
    box.appendChild(el('p', 'hint-block', 'Thank you for choosing Sun Son Solar. Keep this receipt for your records.'));
    box.classList.remove('hidden');
    box.setAttribute('tabindex', '-1');
    box.focus();
  }

  /* ---------- Online payment and receipts (admin) ---------- */
  function adminPaymentRow(b){
