  /* ---------- Technician availability (admin) ---------- */
  function fmtShortDay(s){ return new Date(s + 'T00:00:00').toLocaleDateString('en-PH', { weekday: 'short', day: 'numeric' }); }
  function renderAvailability(){
    var box = document.getElementById('availGrid');
    box.textContent = '';
    var techs = activeTechs();
    if(!techs.length){ box.appendChild(el('p', 'empty', 'No active technicians yet. Add employee accounts in the Users tab.')); return; }
    var days = [];
    for(var i = 0; i < 7; i++){ var d = new Date(); d.setDate(d.getDate() + i); days.push(ymd(d)); }
    var open = allBookings().filter(function(b){ return b.technicianId && (b.status === 'Pending' || b.status === 'Confirmed'); });
    techs.forEach(function(t){
      var row = el('div', 'av-row');
      var name = el('div', 'av-name');
      name.appendChild(el('b', null, staffName(t)));
      name.appendChild(el('span', 'meta', t.department || 'Staff'));
      row.appendChild(name);
      var cells = el('div', 'av-cells');
      days.forEach(function(day){
        var off = (t.timeOff || []).indexOf(day) > -1;
        var jobs = open.filter(function(b){ return b.technicianId === t.id && b.date === day; }).length;
        var label = off ? 'Off' : (jobs ? jobs + (jobs === 1 ? ' job' : ' jobs') : 'Free');
        var cell = el('button', 'av-cell ' + (off ? 'off' : jobs ? 'busy' : 'free'));
        cell.type = 'button';
        cell.setAttribute('aria-label', staffName(t) + ', ' + fmtDate(day) + ': ' + label + '. Tap to ' + (off ? 'make available' : 'mark as off'));
        cell.appendChild(el('span', 'av-day', fmtShortDay(day)));
        cell.appendChild(el('span', 'av-state', label));
        cell.addEventListener('click', function(){
          var next = off ? (t.timeOff || []).filter(function(x){ return x !== day; }) : (t.timeOff || []).concat([day]);
          updateStaff(t.id, { timeOff: next });
        });
        cells.appendChild(cell);
      });
      row.appendChild(cells);
      box.appendChild(row);
    });
  }


  (function(){
    var viewport = document.getElementById('pGrid'), prev = document.getElementById('pPrev'), next = document.getElementById('pNext');
    if(!viewport || !prev || !next) return;

    viewport.addEventListener('click', function(e){
      var b = e.target.closest('[data-quote]');
      if(!b) return;
      quotePreset = b.getAttribute('data-quote');
      showView('quote');
    });

    var cards = Array.prototype.slice.call(viewport.querySelectorAll('.product-card'));
    var n = cards.length;
    if(n < 2) return;

    var track = document.createElement('div');
    track.className = 'prod-track';
    cards.forEach(function(c){ track.appendChild(c); });
    viewport.appendChild(track);

    function clone(card){
      var c = card.cloneNode(true);
      c.classList.add('p-clone');
      c.setAttribute('aria-hidden', 'true');
      Array.prototype.forEach.call(c.querySelectorAll('button, a'), function(x){ x.tabIndex = -1; });
      return c;
    }
    // Copies sit before and after the real cards: [copies][real cards][copies]
    var K = Math.min(3, n);
    var head = document.createDocumentFragment();
    cards.slice(-K).forEach(function(card){ head.appendChild(clone(card)); });
    track.insertBefore(head, track.firstChild);
    var tail = document.createDocumentFragment();
    cards.slice(0, K).forEach(function(card){ tail.appendChild(clone(card)); });
    track.appendChild(tail);

    var pos = K, busy = false;
    var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');

    function step(){
      var gap = parseFloat(getComputedStyle(track).columnGap) || 0;
      return cards[0].offsetWidth + gap;
    }
    function place(animate){
      track.style.transition = (animate && !reduce.matches) ? 'transform .5s ease' : 'none';
      track.style.transform = 'translate3d(' + (-pos * step()) + 'px,0,0)';
    }
    function go(dir){
      if(busy) return;
      busy = true;
      pos += dir;
      place(true);
      var finished = false;
      function finish(){
        if(finished) return;
        finished = true;
        track.removeEventListener('transitionend', finish);
        if(pos >= K + n){ pos -= n; place(false); }
        else if(pos < K){ pos += n; place(false); }
        busy = false;
      }
      track.addEventListener('transitionend', finish);
      setTimeout(finish, 600);
    }

    prev.addEventListener('click', function(){ go(-1); });
    next.addEventListener('click', function(){ go(1); });

    var sx = null;
    viewport.addEventListener('touchstart', function(e){ sx = e.touches[0].clientX; }, { passive: true });
    viewport.addEventListener('touchend', function(e){
      if(sx === null) return;
      var dx = e.changedTouches[0].clientX - sx;
      sx = null;
      if(Math.abs(dx) > 40) go(dx < 0 ? 1 : -1);
    }, { passive: true });

    window.addEventListener('resize', function(){ place(false); });
    window.addEventListener('load', function(){ place(false); });
    place(false);
  })();

  (function(){
    var tabs = document.querySelectorAll('.pj-tab');
    tabs.forEach(function(t){
      t.addEventListener('click', function(){
        tabs.forEach(function(o){
          var on = o === t;
          o.classList.toggle('active', on);
          o.setAttribute('aria-selected', on ? 'true' : 'false');
          document.getElementById(o.getAttribute('data-pj')).hidden = !on;
        });
      });
    });
  })();

  (function(){
    var pin = document.getElementById('projectsPin'), sticky = document.getElementById('projectsSticky'), track = document.getElementById('projectsTrack');
    if(!pin || !sticky || !track) return;
    var cards = Array.prototype.slice.call(track.querySelectorAll('.p-card'));
    var still = window.matchMedia('(prefers-reduced-motion: reduce)');
    var dist = 0, ticking = false;
    function layout(){
      if(still.matches || !pin.offsetParent){ pin.style.height = ''; track.style.transform = ''; cards.forEach(function(c){ c.style.transform = ''; }); return; }
      dist = Math.max(0, track.offsetWidth - sticky.clientWidth);
      pin.style.height = (sticky.offsetHeight + dist) + 'px';
      update();
    }
    function update(){
      ticking = false;
      if(still.matches || !pin.offsetParent) return;
      var top = parseFloat(getComputedStyle(sticky).top) || 0;
      var range = pin.offsetHeight - sticky.offsetHeight;
      var p = range > 0 ? Math.min(1, Math.max(0, (top - pin.getBoundingClientRect().top) / range)) : 0;
      track.style.transform = 'translate3d(' + (-p * dist) + 'px,0,0)';
      cards.forEach(function(c){
        var dx = (p - 0.5) * parseFloat(c.dataset.d) * 140;
        c.style.transform = 'translate3d(' + dx + 'px,' + c.dataset.y + ',0) scale(' + c.dataset.s + ')';
      });
    }
    window.__layoutProjects = layout;
    window.addEventListener('scroll', function(){ if(!ticking){ ticking = true; requestAnimationFrame(update); } }, { passive: true });
    window.addEventListener('resize', layout);
    window.addEventListener('orientationchange', function(){ setTimeout(layout, 250); });
    window.addEventListener('load', layout);
    if(window.ResizeObserver){ new ResizeObserver(function(){ requestAnimationFrame(layout); }).observe(track); }
    if(still.addEventListener) still.addEventListener('change', layout);
    layout();
  })();

  (function(){
    var track = document.getElementById('heroTrack');
    if(!track) return;
    var CARD_MS = 10000;  
    var slides = Array.prototype.slice.call(track.children);
    var count = slides.length;
    if(count < 2) return;
    slides.forEach(function(img){ img.addEventListener('error', function(){ img.style.visibility = 'hidden'; }); });
    slides.forEach(function(img){ track.appendChild(img.cloneNode(true)); });   
    var still = window.matchMedia('(prefers-reduced-motion: reduce)');
    var step = 0, pos = 0, last = 0;
    function measure(){
      var gap = parseFloat(getComputedStyle(track).columnGap) || 0;
      step = slides[0].offsetWidth + gap;
    }
    function frame(now){
      if(!last) last = now;
      var dt = Math.min(now - last, 100); last = now;
      if(step && !still.matches){
        pos = (pos + step * dt / CARD_MS) % (step * count);
        track.style.transform = 'translate3d(' + (-pos) + 'px,0,0)';
      }
      requestAnimationFrame(frame);
    }
    measure();
    window.addEventListener('resize', measure);
    window.addEventListener('load', measure);
    if(window.ResizeObserver){ new ResizeObserver(measure).observe(track.parentNode); }
    requestAnimationFrame(frame);
  })();

  (function(){
    var grid = document.getElementById('tGrid'), prev = document.getElementById('tPrev'), next = document.getElementById('tNext');
    if(!grid || !prev || !next) return;

    var originals = Array.prototype.slice.call(grid.querySelectorAll('.t-card'));
    var n = originals.length;
    if(n < 2) return;

    var K = Math.min(3, n);
    function clone(card){ var c = card.cloneNode(true); c.classList.add('t-clone'); c.setAttribute('aria-hidden', 'true'); return c; }
    originals.slice(-K).forEach(function(card){ grid.insertBefore(clone(card), grid.firstChild); });
    originals.slice(0, K).forEach(function(card){ grid.appendChild(clone(card)); });

    function stepPx(){
      var a = originals[0], b = originals[1];
      return b.offsetLeft - a.offsetLeft;
    }
    function startPos(){ return originals[0].offsetLeft - grid.offsetLeft; }
    function loopWidth(){ return stepPx() * n; }

    function jumpTo(x){  
      grid.style.scrollBehavior = 'auto';
      grid.style.scrollSnapType = 'none';
      grid.scrollLeft = x;
      requestAnimationFrame(function(){ grid.style.scrollSnapType = ''; grid.style.scrollBehavior = ''; });
    }

    function normalize(){
      var x = grid.scrollLeft, s = startPos(), w = loopWidth();
      if(x >= s + w - 1){ jumpTo(x - w); }
      else if(x < s - 1){ jumpTo(x + w); }
    }

    var settleTimer = null, pointerDown = false;
    function onScroll(){
      clearTimeout(settleTimer);
      settleTimer = setTimeout(function(){ if(!pointerDown){ normalize(); target = null; } }, 120);
    }
    grid.addEventListener('scroll', onScroll, { passive: true });
    grid.addEventListener('pointerdown', function(){ pointerDown = true; });
    window.addEventListener('pointerup', function(){ pointerDown = false; onScroll(); });
    window.addEventListener('pointercancel', function(){ pointerDown = false; onScroll(); });
    grid.addEventListener('touchstart', function(){ pointerDown = true; }, { passive: true });
    grid.addEventListener('touchend', function(){ pointerDown = false; onScroll(); }, { passive: true });

    var target = null;
    function go(dir){
      var s = stepPx();
      var base = (target !== null) ? target : Math.round(grid.scrollLeft / s) * s;
      target = base + dir * s;
      grid.scrollTo({ left: target, behavior: 'smooth' });
    }
    prev.addEventListener('click', function(){ go(-1); });
    next.addEventListener('click', function(){ go(1); });

    function init(){ target = null; jumpTo(startPos()); }
    window.addEventListener('resize', init);
    window.addEventListener('load', init);
    if(window.ResizeObserver){ new ResizeObserver(function(){ requestAnimationFrame(init); }).observe(grid); }
    init();
  })();

    document.getElementById('year').textContent = new Date().getFullYear();
  (function(){ var r = pageFromHash(location.hash); if(r){ currentPage = r.page; pendingScroll = r.scrollId; } })();
  showView('guest');
  if(pendingScroll){ var _id = pendingScroll; pendingScroll = null; setTimeout(function(){ var t = document.getElementById(_id); if(t) t.scrollIntoView(); }, 50); }

  api('/api/me', 'GET').then(function(d){ if(d.ok) setUser(d); }).catch(function(){});

})();

</script>
<script>
(function(){
  var CATS = {
    tech:    { label:'Solar Technology', cls:'t-tech',    thumb:'thumb-tech',    icon:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M4.900 4.900l2.100 2.100M17 17l2.100 2.100M4.900 19.100L7 17M17 7l2.100-2.100"/>' },
    company: { label:'Company News',     cls:'t-company', thumb:'thumb-company', icon:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h3M13 7h3M8 11h3M13 11h3M10 21v-5h4v5"/>' },
    award:   { label:'Achievements',     cls:'t-award',   thumb:'thumb-award',   icon:'<circle cx="12" cy="9" r="6"/><path d="M8.500 14L7 22l5-3 5 3-1.500-8"/>' }
  };
  var POSTS = [
    { id:'milestone', img:'https://images.unsplash.com/photo-1658298775754-5839ffd434cc?auto=format&fit=crop&w=900&q=70', cat:'award', featured:true, date:'October 6, 2026', read:'3 min read',
      title:'Sun Son Solar Reaches 3,500 Installed Systems',
      excerpt:'From a small shop in Pasig City to thousands of rooftops across Metro Manila and nearby provinces, we look back at a milestone made possible by our customers.',
      body:['This month our installation teams completed the 3,500th solar system installed by Sun Son Solar. Homes, shops, offices, and warehouses now generate their own clean power thanks to the trust our customers have placed in us.',
            'Every one of those systems began with a free consultation and a careful look at the customer\u2019s electricity bills. We believe the right system is the one sized to how you actually use power, not the biggest one we can sell.',
            'We thank every customer, supplier, and team member who helped us get here. The next milestone is already underway, and we will keep sharing our progress on this page.'] },
    { id:'bifacial', img:'https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=900&q=70', cat:'tech', date:'September 28, 2026', read:'4 min read',
      title:'How Bifacial Solar Panels Collect Light From Both Sides',
      excerpt:'Bifacial panels catch sunlight on the front and reflected light on the back. Here is when the extra cost makes sense.',
      body:['A bifacial solar panel has active cells on both faces. The front works like any standard panel, while the rear picks up light reflected from the ground, a light-colored roof, or nearby walls.',
            'The extra energy depends on the surface under the panels and how high they are mounted. Bright, reflective surfaces and open mounting give the biggest gain, while dark roofs mounted flat give very little.',
            'Bifacial panels often suit ground mounts and flat commercial roofs. For a typical pitched home roof, a standard panel may be the better value. Ask us for a free consultation and we will compare both for your site.'] },
    { id:'safety', img:'https://images.unsplash.com/photo-1724041875334-0a6397111c7e?auto=format&fit=crop&w=900&q=70', cat:'company', date:'September 19, 2026', read:'2 min read',
      title:'Our Teams Complete Another Round of Safety Training',
      excerpt:'Working at heights and with electricity demands constant practice. Our installers refreshed their skills this month.',
      body:['All of our installation crews took part in a refresher course covering fall protection, electrical isolation, and safe handling of panels and batteries.',
            'Training is a regular part of how we work, not a one-time event. Every new technician also shadows an experienced crew before leading a job on their own.',
            'Safe crews make better installations, and that is a promise we want every customer to feel when our team arrives at their door.'] },
    { id:'hybrid', img:'https://images.unsplash.com/photo-1558449028-b53a39d100fc?auto=format&fit=crop&w=900&q=70', cat:'tech', date:'September 10, 2026', read:'4 min read',
      title:'Hybrid Inverters: One Box for Solar, Battery, and Grid',
      excerpt:'A hybrid inverter manages your panels, your battery, and the grid together. We explain why more homes are choosing one.',
      body:['A traditional grid-tied inverter turns the direct current from your panels into the alternating current your home uses. A hybrid inverter does that and also manages a battery and decides when to draw from the grid.',
            'The main advantage is flexibility. You can start with panels only and add a battery later without replacing your inverter, and during a power outage the system can keep selected circuits running.',
            'Hybrid inverters usually cost more than grid-tied models, so they make the most sense for customers who want backup power or expect to add storage in the future.'] },
    { id:'award', img:'https://images.unsplash.com/photo-1508514177221-188b1cf16e9d?auto=format&fit=crop&w=900&q=70', cat:'award', date:'August 30, 2026', read:'2 min read',
      title:'Customer Choice Award Recognizes Our After-Sales Service',
      excerpt:'Quality products and a service team that answers the phone: the qualities our customers say matter most.',
      body:['Sun Son Solar has been honored with a regional Customer Choice Award for quality product distribution and dependable after-sales service.',
            'The award belongs to our service team, who respond to maintenance calls, repair faults, and check on systems long after the installation is finished.',
            'We will keep working to deserve the trust that this recognition represents.'] },
    { id:'batteries', img:'https://images.unsplash.com/photo-1613665813446-82a78c468a1d?auto=format&fit=crop&w=900&q=70', cat:'tech', date:'August 18, 2026', read:'5 min read',
      title:'Lithium vs. Lead-Acid Batteries: What Suits Your Home?',
      excerpt:'Both can store solar energy, but they differ in lifespan, usable capacity, and price. A simple guide to choosing.',
      body:['Lead-acid batteries cost less up front and are well understood, but they are usually discharged only about half way to protect their life, and they need more care.',
            'Lithium iron phosphate batteries cost more at first, yet they typically allow deeper daily use, last for many more charge cycles, and need very little maintenance.',
            'For a home that uses its battery every day, lithium often costs less over its whole life. For occasional backup on a tight budget, lead-acid can still make sense. We will help you compare both options.'] },
    { id:'app', img:'https://images.unsplash.com/photo-1594818379496-da1e345b0ded?auto=format&fit=crop&w=900&q=70', cat:'company', date:'August 4, 2026', read:'2 min read',
      title:'Remote Monitoring Now Available to All Customers',
      excerpt:'Check how much power your system makes from your phone, and let us spot problems before you notice them.',
      body:['Every new installation now includes remote monitoring, and existing customers can ask our team to add it to their systems.',
            'You can see daily and monthly production, compare it with your electricity use, and receive an alert if output drops unexpectedly. Our team can also look at the data when you call for support.',
            'Contact us to ask whether your current system can be connected.'] },
    { id:'habits', img:'https://images.unsplash.com/photo-1497440001374-f26997328c1b?auto=format&fit=crop&w=900&q=70', cat:'tech', date:'July 22, 2026', read:'3 min read',
      title:'5 Simple Habits That Keep Your Solar Panels Performing',
      excerpt:'A few minutes of care each month helps your system produce more for longer.',
      body:['Rinse the panels with clean water when dust, bird droppings, or leaves build up, and avoid high-pressure sprays or harsh scrubbing that can damage the glass.',
            'Trim nearby branches that cast shade, check your production regularly so you notice sudden drops, and keep the area around the inverter clear and ventilated.',
            'Finally, book a yearly inspection. Our technicians check wiring, mounting, and connections that are hard to see from the ground.'] }
  ];

  var state = { filter:'all', last:null };
  var featuredBox = document.getElementById('blogFeatured');
  var grid = document.getElementById('blogGrid');
  var filters = document.getElementById('blogFilters');
  var modal = document.getElementById('blogModal');
  var SVGNS = 'http://www.w3.org/2000/svg';

  function make(tag, cls, text){ var e = document.createElement(tag); if(cls) e.className = cls; if(text != null) e.textContent = text; return e; }
  function thumb(post){
    var cat = post.cat;
    var d = make('div', 'post-thumb ' + CATS[cat].thumb); d.setAttribute('aria-hidden','true');
    var svg = document.createElementNS(SVGNS, 'svg');
    svg.setAttribute('viewBox','0 0 24 24'); svg.setAttribute('fill','none'); svg.setAttribute('stroke','currentColor');
    svg.setAttribute('stroke-width','1.8'); svg.setAttribute('stroke-linecap','round'); svg.setAttribute('stroke-linejoin','round');
    svg.innerHTML = CATS[cat].icon; // static trusted markup defined above
    d.appendChild(svg);
    if(post.img){
      var im = document.createElement('img');
      im.alt = ''; im.loading = 'lazy'; im.referrerPolicy = 'no-referrer'; im.src = post.img;
      im.onerror = function(){ im.remove(); }; // falls back to the colored placeholder
      d.appendChild(im);
    }
    return d;
  }
  function meta(post){
    var m = make('p','blog-meta');
    m.appendChild(make('span','blog-tag ' + CATS[post.cat].cls, CATS[post.cat].label));
    m.appendChild(make('span', null, post.date));
    m.appendChild(make('span', null, post.read));
    return m;
  }

  function openPost(post, trigger){
    state.last = trigger || null;
    var hero = document.getElementById('blogModalImg'); hero.textContent = ''; hero.appendChild(thumb(post));
    var m = document.getElementById('blogModalMeta'); m.textContent = '';
    m.appendChild(make('span','blog-tag ' + CATS[post.cat].cls, CATS[post.cat].label));
    m.appendChild(make('span', null, post.date));
    m.appendChild(make('span', null, post.read));
    document.getElementById('blogModalTitle').textContent = post.title;
    var body = document.getElementById('blogModalBody'); body.textContent = '';
    post.body.forEach(function(t){ body.appendChild(make('p', null, t)); });
    var sbw = window.innerWidth - document.documentElement.clientWidth; // keep layout from jumping when the scrollbar hides
    if(sbw > 0) document.body.style.paddingRight = sbw + 'px';
    modal.classList.remove('hidden');
    document.documentElement.classList.add('blog-lock');
    document.body.classList.add('modal-open');
    modal.scrollTop = 0;
    document.getElementById('blogModalClose').focus();
  }
  function closePost(){
    modal.classList.add('hidden');
    document.documentElement.classList.remove('blog-lock');
    document.body.classList.remove('modal-open');
    document.body.style.paddingRight = '';
    if(state.last && document.contains(state.last)) state.last.focus();
  }

  function render(){
    featuredBox.textContent = '';
    var feat = POSTS.filter(function(p){ return p.featured; })[0];
    if(feat && state.filter === 'all'){
      var box = make('article','blog-featured');
      box.appendChild(thumb(feat));
      var txt = make('div');
      txt.appendChild(meta(feat));
      txt.appendChild(make('h2', null, feat.title));
      txt.appendChild(make('p','ex', feat.excerpt));
      var btn = make('button','btn btn-primary','Read the full story'); btn.type = 'button';
      btn.addEventListener('click', function(){ openPost(feat, btn); });
      txt.appendChild(btn); box.appendChild(txt); featuredBox.appendChild(box);
    }
    grid.textContent = '';
    POSTS.filter(function(p){
      if(state.filter === 'all') return !p.featured;
      return p.cat === state.filter;
    }).forEach(function(p){
      var c = make('button','post-card'); c.type = 'button';
      c.appendChild(thumb(p));
      c.appendChild(meta(p));
      c.appendChild(make('h3', null, p.title));
      c.appendChild(make('p', null, p.excerpt));
      c.appendChild(make('span','read-more','Read more \u2192'));
      c.addEventListener('click', function(){ openPost(p, c); });
      grid.appendChild(c);
    });
  }

  [['all','All posts']].concat(Object.keys(CATS).map(function(k){ return [k, CATS[k].label]; })).forEach(function(f){
    var b = make('button','chip', f[1]); b.type = 'button';
    b.setAttribute('aria-pressed', f[0] === state.filter ? 'true' : 'false');
    b.addEventListener('click', function(){
      state.filter = f[0];
      filters.querySelectorAll('.chip').forEach(function(x){ x.setAttribute('aria-pressed', x === b ? 'true' : 'false'); });
      render();
    });
    filters.appendChild(b);
  });

  document.getElementById('blogModalClose').addEventListener('click', closePost);
  document.getElementById('blogModalX').addEventListener('click', closePost);
  modal.addEventListener('click', function(e){ if(e.target === modal) closePost(); });
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape' && !modal.classList.contains('hidden')) closePost(); });
  render();
})();
</script>
</body>
</html>
